mapper.update:
UPDATE users
SET    reg_user = #{userNo}
WHERE  user_no  = #{userNo}

mapper.select:
SELECT user_no AS userNo -- 사용자 번호 , user_id AS userId -- 사용자 아이디 , user_name AS userName -- 사용자 이름 , role AS role -- 권한(SYSTEM/ADMIN/USER) , status AS status -- 계정상태(ACTIVE/DISABLED) FROM users
ORDER BY user_no DESC
LIMIT #{firstIndex}, #{recordCountPerPage}
